import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
from scipy.optimize import minimize
L=Chem.MolFromMolFile('ligand.mol',removeHs=False)
ffL=AllChem.MMFFGetMoleculeForceField(L,AllChem.MMFFGetMoleculeProperties(L))
rw=Chem.RWMol()
for i in range(10):
 a=Chem.Atom('C')
 if i==0:a.SetFormalCharge(-1)
 if i<5:a.SetIsAromatic(True)
 rw.AddAtom(a)
for i in range(5):rw.AddBond(i,(i+1)%5,Chem.BondType.AROMATIC);rw.AddBond(i,i+5,Chem.BondType.SINGLE)
cp=rw.GetMol();Chem.SanitizeMol(cp);cp=Chem.AddHs(cp)
c=Chem.Conformer(25)
lines=open('initial.xyz').readlines()[2:];sym=[l.split()[0] for l in lines];x0=np.array([list(map(float,l.split()[1:])) for l in lines])
for i in range(25):c.SetAtomPosition(i,x0[i+89])
cp.AddConformer(c);Chem.MolToMolFile(cp,'cp.mol');ffC=AllChem.MMFFGetMoleculeForceField(cp,AllChem.MMFFGetMoleculeProperties(cp))
# index groups with centroid weights
terms=[]
def term(ids1,ids2,target,k): terms.append((np.array(ids1),np.array(ids2),target,k))
for i,target,k in [(1,2.30,160),(23,2.28,160),(24,2.28,160),(0,3.48,10),(2,3.48,10),(3,3.40,4)]:term([88],[i],target,k)
for j in range(89,94):term([88],[j],2.20,120)
term([88],[114],1.60,200)
term(list(range(89,94)),[1],3.65,20)
term(list(range(89,94)),[23,24],3.55,20)
term(list(range(89,94)),[114],3.14,10)
term([114],[1],2.85,10);term([114],[23,24],2.70,10)
rads={'C':1.7,'H':1.1,'P':1.8,'Ir':1.4}
ai=[];aj=[];mins=[]
for i in range(88):
 for j in range(89,115):
  ai.append(i);aj.append(j);mins.append(.88*(rads[sym[i]]+rads[sym[j]]))
for i in range(88):
 if i not in [1,23,24]:ai.append(i);aj.append(88);mins.append(2.85 if sym[i]=='C' else 2.05)
for j in range(89,114):ai.append(114);aj.append(j);mins.append(2.30 if sym[j]=='C' else 1.80)
ai=np.array(ai);aj=np.array(aj);mins=np.array(mins)
def fun(v):
 x=v.reshape(-1,3);g=np.zeros_like(x)
 e=ffL.CalcEnergy(x[:88].ravel().tolist())+ffC.CalcEnergy(x[89:114].ravel().tolist())
 g[:88]=np.array(ffL.CalcGrad(x[:88].ravel().tolist())).reshape(-1,3)
 g[89:114]=np.array(ffC.CalcGrad(x[89:114].ravel().tolist())).reshape(-1,3)
 for a,b,t,k in terms:
  d=x[a].mean(axis=0)-x[b].mean(axis=0);r=np.linalg.norm(d);err=r-t;e+=k*err*err
  dg=2*k*err*d/r;g[a]+=dg/len(a);g[b]-=dg/len(b)
 delta=x[ai]-x[aj];r=np.linalg.norm(delta,axis=1);err=np.minimum(r-mins,0);e+=80*np.sum(err*err)
 dg=160*err[:,None]*delta/r[:,None];np.add.at(g,ai,dg);np.add.at(g,aj,-dg)
 return e,g.ravel()
results=[]
# Optimize both sides of the phosphine/arene chelate
for face in [1,-1]:
 x=x0.copy()
 if face==-1:
  p=x[1]-x[88];a=(x[23]+x[24])/2-x[88];n=np.cross(p,a);n/=np.linalg.norm(n)
  for i in range(89,115):x[i]-=2*np.dot(x[i]-x[88],n)*n
 for repeat in range(2):
  out=minimize(fun,x.ravel(),jac=True,method='L-BFGS-B',options={'maxiter':2200,'ftol':1e-10,'gtol':1e-4,'maxls':40})
  x=out.x.reshape(-1,3);results.append((out.fun,x.copy()))
  print('face',face,'repeat',repeat,'energy',out.fun,'success',out.success,flush=True)
  with open(f'refined_{face}_{repeat}.xyz','w') as f:
   f.write('115\nCp*Ir(H)(terphenylphosphine) cation; charge +1\n')
   for s,v in zip(sym,x):f.write(f'{s} {v[0]:.9f} {v[1]:.9f} {v[2]:.9f}\n')
results.sort(key=lambda t:t[0]);x=results[0][1];x-=x[88]
with open('refined.xyz','w') as f:
 f.write('115\nCp*Ir(H)(terphenylphosphine) cation; charge +1\n')
 for s,v in zip(sym,x):f.write(f'{s} {v[0]:.9f} {v[1]:.9f} {v[2]:.9f}\n')
print('DONE',flush=True)
PY
